when.set-body:
@{
                    return new JObject(
                        new JProperty("error", "backend_authentication_failed"),
                        new JProperty("message", "APIM could not obtain a Microsoft Entra token for the Speech backend. Verify the managed identity has the 'Cognitive Services Speech User' role on the Speech resource."),
                        new JProperty("details", context.LastError?.Message)
                    ).ToString();
                }

otherwise.set-body:
@{
                    return new JObject(
                        new JProperty("error", "speech_gateway_error"),
                        new JProperty("message", context.LastError?.Message ?? "An unexpected error occurred while contacting the Speech backend."),
                        new JProperty("source", context.LastError?.Source),
                        new JProperty("reason", context.LastError?.Reason)
                    ).ToString();
                }
